/* Standalone SPU decode test - runs under node via emcc build.
 * Links only src/web/psx/spu.c; VAG + expected PCM from
 * .tmp_test/vag_ss3.h (generated by tools/vag_decode.py).
 *
 * Pitch 0x1000 = 44100 Hz: output sample k should equal decoded
 * sample k once the ADSR envelope is full (we key with instant
 * attack/sustain-max and skip a settle margin).
 */
#include <stdio.h>
#include <stdint.h>
#include "../psx/spu.h"
#include "../../../.tmp_test/vag_ss3.h"

#define VADDR 0x1010

static int16_t out[60000];

int main(void)
{
	int i, fails = 0;
	int n = (int)(sizeof(vag_test_pcm) / sizeof(vag_test_pcm[0]));

	/* SPU RAM is emulated; DMA the vag body in */
	spu_dma_write(VADDR, vag_test_bytes, sizeof(vag_test_bytes));

	/* voice 0: vol full, pitch 1:1, instant attack, sustain max */
	spu_write_reg16(0x1F801C00 + 0, 0x7FFF);      /* VOLL */
	spu_write_reg16(0x1F801C00 + 2, 0x7FFF);      /* VOLR */
	spu_write_reg16(0x1F801C00 + 4, 0x1000);      /* PITCH */
	spu_write_reg16(0x1F801C00 + 6, VADDR >> 3);  /* START */
	spu_write_reg16(0x1F801C00 + 8, 0x00FF);      /* ADSR1: ar max, lin, sl=0xF */
	spu_write_reg16(0x1F801C00 + 10, 0x0000);     /* ADSR2: sr=0 (hold) */
	spu_write_reg16(0x1F801C00 + 0x180, 0x7FFF);  /* MVOLL */
	spu_write_reg16(0x1F801C00 + 0x182, 0x7FFF);  /* MVOLR */
	spu_write_reg16(0x1F801C00 + 0x188, 0x0001);  /* KON v0 */

	if (n > 29500) n = 29500;
	spu_render(out, n + 200);

	/* pitch 0x1000: env ramp shifts alignment slightly; find
	 * best small offset then compare */
	{
		int bestoff = 0, besterr = 1 << 30;
		int o;
		for (o = -4; o <= 4; o++) {
			long e = 0;
			for (i = 100; i < 200; i++) {
				long d = out[(i + o) * 2] - vag_test_pcm[i];
				e += d < 0 ? -d : d;
			}
			if (e < besterr) { besterr = e; bestoff = o; }
		}
		for (i = 96; i < 112; i++)
			printf("i=%d out=%d exp=%d\n", i, out[(i+bestoff)*2],
			       vag_test_pcm[i]);
		{
			int maxd = 0, firstbad = -1;
			long so = 0, se = 0, sd = 0;
			for (i = 64; i < n; i++) {
				int d = out[(i + bestoff) * 2] - vag_test_pcm[i];
				if (d < 0) d = -d;
				if (d > maxd) maxd = d;
				if (d > 900 && firstbad < 0) firstbad = i;
				so += out[(i+bestoff)*2] < 0 ? -out[(i+bestoff)*2] : out[(i+bestoff)*2];
				se += vag_test_pcm[i] < 0 ? -vag_test_pcm[i] : vag_test_pcm[i];
				sd += d;
			}
			printf("pitch 0x1000: offset=%d maxdiff=%d firstbad=%d "
			       "sum|out|=%ld sum|exp|=%ld ratio=%.4f avgdiff=%ld\n",
			       bestoff, maxd, firstbad, so, se,
			       (double)so / se, sd / (n - 64));
			if (sd / (n - 64) > 1500) fails++;
			if ((double)so / se < 0.7 || (double)so / se > 1.1)
				fails++;
		}
	}

	/* half-speed check at pitch 0x0800 */
	spu_reset();
	spu_dma_write(VADDR, vag_test_bytes, sizeof(vag_test_bytes));
	spu_write_reg16(0x1F801C00 + 0, 0x7FFF);
	spu_write_reg16(0x1F801C00 + 2, 0x7FFF);
	spu_write_reg16(0x1F801C00 + 6, VADDR >> 3);
	spu_write_reg16(0x1F801C00 + 8, 0x00FF);
	spu_write_reg16(0x1F801C00 + 10, 0x0000);
	spu_write_reg16(0x1F801C00 + 0x180, 0x7FFF);
	spu_write_reg16(0x1F801C00 + 0x182, 0x7FFF);
	{
		int16_t o2[60000];
		spu_render(o2, 64);
		spu_write_reg16(0x1F801C00 + 4, 0x0800);
		spu_write_reg16(0x1F801C00 + 0x188, 0x0001);
		spu_render(o2, 22000);
		{
			int k, mx=0;
			for (k=0;k<22000;k++) { int a=o2[k*2]; if (a<0)a=-a; if (a>mx)mx=a; }
			printf("o2 max=%d\n", mx);
		}
		/* output[i] ~ pcm[(i-lag)/2]; scan lag for best fit */
		{
			int bl = 0; long be = 1L << 40;
			int lag;
			for (lag = 0; lag < 32; lag += 2) {
				long e = 0;
				for (i = 400; i < 4000; i += 4) {
					long d = o2[i * 2] - vag_test_pcm[(i - lag) / 2];
					e += d < 0 ? -d : d;
				}
				if (e < be) { be = e; bl = lag; }
			}
			printf("pitch 0x0800: lag=%d avgdiff=%ld\n",
			       bl, be / 900);
			if (be / 900 > 6000) fails++;
		}
	}

	printf(fails ? "spu_test: FAIL %d\n" : "spu_test: pass\n", fails);
	return fails;
}
